// Embedded base64 ROMs for zero-latency instant startup without network dependency
export const SUPER_MARIO_BROS_BASE64 = '';
export const MARIO_BROS_CLASSIC_BASE64 = '';

export function base64ToUint8Array(base64: string): Uint8Array {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}
